<script setup lang="ts">defineProps<{article:{slug:string;category:string;readTime:string;title:string;excerpt:string;image:string}}>()</script><template><article class="card"><NuxtLink :to="`/actualites/${article.slug}`" class="cover"><img :src="article.image" :alt="article.title" loading="lazy"><span><i class="pi pi-arrow-up-right"/></span></NuxtLink><div class="body"><div class="meta"><b>{{article.category}}</b><span>{{article.readTime}} de lecture</span></div><h3><NuxtLink :to="`/actualites/${article.slug}`">{{article.title}}</NuxtLink></h3><p>{{article.excerpt}}</p><NuxtLink :to="`/actualites/${article.slug}`" class="read">Lire l’article <i class="pi pi-arrow-right"/></NuxtLink></div></article></template><style scoped>.card{overflow:hidden;border:1px solid #21142f10;border-radius:24px;background:white;transition:.25s}.card:hover{transform:translateY(-5px);box-shadow:0 20px 45px #21142f10}.cover{display:block;height:220px;position:relative;overflow:hidden}.cover img{width:100%;height:100%;object-fit:cover;transition:transform .5s}.card:hover img{transform:scale(1.04)}.cover span{position:absolute;right:15px;bottom:15px;width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:white;color:#48265f}.body{padding:23px}.meta{display:flex;justify-content:space-between;gap:8px;font-size:10px;color:#8c8191}.meta b{color:#76508c;text-transform:uppercase;letter-spacing:.1em}.body h3{font-size:20px;line-height:1.25;margin:15px 0 10px;color:#21142f}.body p{font-size:12px;line-height:1.75;color:#756d7b}.read{display:inline-flex;gap:10px;align-items:center;font-size:11px;font-weight:800;color:#48265f;margin-top:9px}</style>